<?php
$raw=(string)($_GET['url']??'');if(strlen($raw)>1800){http_response_code(400);exit;}$u=parse_url($raw);$allowed=['resultados365.com','www.resultados365.com','lotoven.com','www.lotoven.com','loteriadehoy.com','www.loteriadehoy.com'];if(!$u||($u['scheme']??'')!=='https'||!in_array(strtolower($u['host']??''),$allowed,true)||isset($u['user'])||isset($u['pass'])||isset($u['port'])){http_response_code(400);exit;}
$dir=__DIR__.'/cache_imagenes';if(!is_dir($dir))@mkdir($dir,0755,true);$id=hash('sha256',$raw);$file="$dir/$id.bin";$typeFile="$dir/$id.mime";
if(is_file($file)&&filesize($file)>0&&time()-filemtime($file)<86400){header('Content-Type: '.(file_get_contents($typeFile)?:'image/png'));header('Cache-Control: public, max-age=86400');readfile($file);exit;}
if(!extension_loaded('curl')){http_response_code(503);exit;}
$ch=curl_init($raw);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>3,CURLOPT_TIMEOUT=>8,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_USERAGENT=>'Mozilla/5.0',CURLOPT_MAXFILESIZE=>2000000]);$bytes=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);$mime=strtolower(trim(explode(';',curl_getinfo($ch,CURLINFO_CONTENT_TYPE)?:'')[0]));curl_close($ch);
if($code!==200||!is_string($bytes)||strlen($bytes)>2000000||strlen($bytes)<20||!in_array($mime,['image/png','image/jpeg','image/webp','image/gif'],true)){if(is_file($file)){header('Content-Type: '.(file_get_contents($typeFile)?:'image/png'));readfile($file);exit;}http_response_code(404);exit;}
if(is_dir($dir)&&is_writable($dir)){@file_put_contents($file,$bytes,LOCK_EX);@file_put_contents($typeFile,$mime,LOCK_EX);}header('Content-Type: '.$mime);header('Cache-Control: public, max-age=86400');echo $bytes;
